import type { PersistedAppState, ProviderId } from "./types";

export interface TopicActivity {
  key: string;
  label: string;
  source: "generated artifact" | "lesson title";
  lastStudiedAt: number;
  turns: number;
}

export interface ModelActivity {
  key: string;
  provider: ProviderId;
  model: string;
  replies: number;
  tokens: number;
}

export interface MobileUsageSummary {
  lessons: number;
  messages: number;
  assistantReplies: number;
  attachments: number;
  artifacts: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  reportedCostUsd: number;
  helpful: number;
  missed: number;
  topics: TopicActivity[];
  models: ModelActivity[];
  recentLessons: Array<{ id: string; title: string; updatedAt: number; messages: number }>;
}

function topicKey(label: string): string {
  return label.trim().toLocaleLowerCase().replace(/\s+/g, " ");
}

export function buildMobileUsageSummary(state: PersistedAppState): MobileUsageSummary {
  const meaningfulSessions = state.sessions.filter((session) => session.messages.length > 0);
  const allMessages = meaningfulSessions.flatMap((session) => session.messages);
  const assistantMessages = allMessages.filter((message) => message.role === "assistant");
  const topicMap = new Map<string, TopicActivity>();

  for (const session of meaningfulSessions) {
    if (session.title === "New lesson" || !session.title.trim()) continue;
    const key = topicKey(session.title);
    const prior = topicMap.get(key);
    topicMap.set(key, {
      key,
      label: session.title,
      source: prior?.source ?? "lesson title",
      lastStudiedAt: Math.max(prior?.lastStudiedAt ?? 0, session.updatedAt),
      turns: (prior?.turns ?? 0) + session.messages.length,
    });
  }
  for (const artifact of state.artifacts) {
    if (!artifact.topic?.trim()) continue;
    const key = topicKey(artifact.topic);
    const prior = topicMap.get(key);
    topicMap.set(key, {
      key,
      label: artifact.topic,
      source: "generated artifact",
      lastStudiedAt: Math.max(prior?.lastStudiedAt ?? 0, artifact.createdAt),
      turns: prior?.turns ?? 0,
    });
  }

  const modelMap = new Map<string, ModelActivity>();
  for (const message of assistantMessages) {
    if (!message.provider || !message.model) continue;
    const key = `${message.provider}:${message.model}`;
    const prior = modelMap.get(key);
    modelMap.set(key, {
      key,
      provider: message.provider,
      model: message.model,
      replies: (prior?.replies ?? 0) + 1,
      tokens: (prior?.tokens ?? 0) + (message.usage?.totalTokens ?? 0),
    });
  }

  return {
    lessons: meaningfulSessions.length,
    messages: allMessages.length,
    assistantReplies: assistantMessages.length,
    attachments: allMessages.reduce((total, message) => total + (message.attachments?.length ?? 0), 0),
    artifacts: state.artifacts.length,
    inputTokens: assistantMessages.reduce((total, message) => total + (message.usage?.inputTokens ?? 0), 0),
    outputTokens: assistantMessages.reduce((total, message) => total + (message.usage?.outputTokens ?? 0), 0),
    totalTokens: assistantMessages.reduce((total, message) => total + (message.usage?.totalTokens ?? 0), 0),
    reportedCostUsd: assistantMessages.reduce((total, message) => total + (message.usage?.costUsd ?? 0), 0),
    helpful: state.learnerFeedback.helpful,
    missed: state.learnerFeedback.missed,
    topics: [...topicMap.values()].sort((a, b) => b.lastStudiedAt - a.lastStudiedAt),
    models: [...modelMap.values()].sort((a, b) => b.replies - a.replies || b.tokens - a.tokens),
    recentLessons: meaningfulSessions
      .map((session) => ({ id: session.id, title: session.title, updatedAt: session.updatedAt, messages: session.messages.length }))
      .sort((a, b) => b.updatedAt - a.updatedAt)
      .slice(0, 8),
  };
}

import { useMemo } from "react";
import { useRouter } from "expo-router";
import { StyleSheet, Text, View } from "react-native";
import { Button } from "@/components/Buttons";
import { Screen } from "@/components/Screen";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import { providerDefinition } from "@/lib/provider-config";
import { buildMobileUsageSummary } from "@/lib/usage-summary";
import { useKeating } from "@/state/KeatingProvider";

export default function UsageScreen() {
  const router = useRouter();
  const { state } = useKeating();
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const summary = useMemo(() => buildMobileUsageSummary(state), [state]);

  return (
    <Screen
      title="Usage & study activity"
      subtitle="A local record of your lessons, sources, model usage, and study topics"
      action={<Button compact variant="quiet" onPress={() => router.back()}>Back</Button>}
    >
      <View style={styles.metrics}>
        <Metric label="Lessons" value={formatNumber(summary.lessons)} styles={styles} />
        <Metric label="Messages" value={formatNumber(summary.messages)} styles={styles} />
        <Metric label="Tokens" value={formatNumber(summary.totalTokens)} styles={styles} />
        <Metric label="Saved items" value={formatNumber(summary.artifacts)} styles={styles} />
        <Metric label="Attachments" value={formatNumber(summary.attachments)} styles={styles} />
        <Metric label="Feedback" value={formatNumber(summary.helpful + summary.missed)} styles={styles} />
      </View>

      <Text style={styles.provenance}>
        Topics below come from lesson titles and generated artifacts. Keating does not infer mastery from a title alone.
      </Text>

      <Section title="What you have been studying" styles={styles}>
        {summary.topics.length ? summary.topics.map((topic) => (
          <DataRow
            key={topic.key}
            title={topic.label}
            detail={`${topic.source} · ${topic.turns ? `${topic.turns} messages · ` : ""}${formatDate(topic.lastStudiedAt)}`}
            styles={styles}
          />
        )) : <EmptyCopy text="Start a named lesson or generate a study artifact to build this list." styles={styles} />}
      </Section>

      <Section title="Model usage" styles={styles}>
        {summary.models.length ? summary.models.map((model) => (
          <DataRow
            key={model.key}
            title={`${providerDefinition(model.provider).label} · ${model.model}`}
            detail={`${model.replies} ${model.replies === 1 ? "reply" : "replies"} · ${formatNumber(model.tokens)} reported tokens`}
            styles={styles}
          />
        )) : <EmptyCopy text="Model and token totals begin with replies created by this version." styles={styles} />}
        <View style={styles.tokenBreakdown}>
          <Text style={styles.tokenLine}>Input {formatNumber(summary.inputTokens)}</Text>
          <Text style={styles.tokenLine}>Output {formatNumber(summary.outputTokens)}</Text>
          {summary.reportedCostUsd > 0 ? <Text style={styles.tokenLine}>Reported cost ${summary.reportedCostUsd.toFixed(4)}</Text> : null}
        </View>
      </Section>

      <Section title="Learning signals" styles={styles}>
        <DataRow title="Helpful responses" detail={formatNumber(summary.helpful)} styles={styles} />
        <DataRow title="Responses needing work" detail={formatNumber(summary.missed)} styles={styles} />
        <Text style={styles.provenance}>
          Quiz mastery, spaced-repetition retention, goals, and evidence confidence require the shared learner repository and are not fabricated here.
        </Text>
      </Section>

      <Section title="Recent lessons" styles={styles}>
        {summary.recentLessons.length ? summary.recentLessons.map((lesson) => (
          <DataRow
            key={lesson.id}
            title={lesson.title}
            detail={`${lesson.messages} messages · ${formatDate(lesson.updatedAt)}`}
            styles={styles}
          />
        )) : <EmptyCopy text="Your recent lessons will appear here." styles={styles} />}
      </Section>
    </Screen>
  );
}

function Metric({ label, value, styles }: { label: string; value: string; styles: ReturnType<typeof createStyles> }) {
  return <View style={styles.metric}><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View>;
}

function Section({ title, children, styles }: { title: string; children: React.ReactNode; styles: ReturnType<typeof createStyles> }) {
  return <View style={styles.section}><Text style={styles.sectionTitle}>{title}</Text>{children}</View>;
}

function DataRow({ title, detail, styles }: { title: string; detail: string; styles: ReturnType<typeof createStyles> }) {
  return <View style={styles.row}><Text style={styles.rowTitle}>{title}</Text><Text style={styles.rowDetail}>{detail}</Text></View>;
}

function EmptyCopy({ text, styles }: { text: string; styles: ReturnType<typeof createStyles> }) {
  return <Text style={styles.empty}>{text}</Text>;
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(undefined, { notation: value >= 10_000 ? "compact" : "standard", maximumFractionDigits: 1 }).format(value);
}

function formatDate(timestamp: number): string {
