  for (const attachment of message.attachments ?? []) {
    if (attachment.encoding === "text") {
      parts.push({ text: textAttachmentBlock(attachment) });
    } else {
      parts.push({ inlineData: { mimeType: attachment.mimeType, data: attachmentData(attachment) } });
